scenario.en:
// Slot's naive handler merge:
merged.onClick = (event) => {
  childProps.onClick?.(event);  // the Link's handler
  slotProps.onClick?.(event);   // the Button's handler
};

<Button asChild onClick={(e) => track("upgrade_click")}>
  <Link to="/billing" />
</Button>
// Link's internal onClick: e.preventDefault(); router.push("/billing")

